const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const weights = input.slice(1, 1 + n);

const sum = weights.reduce((acc, x) => acc + x, 0);
const target = sum / n;

const output = weights.map(x => target - x);
console.log(output.join('\n'));
